articles = []
for idx, (title, category, summary, icon, feature) in enumerate(lessons, 1):
    paragraphs = [f'{title.upper()} — ПРАКТИЧЕСКИЙ МОДУЛЬ {idx:02d}.', f'{summary}.'] + core
    paragraphs += [f'Задание {idx}. Открой бинарник AtlasLabX и найди участки, которые соответствуют теме «{title}». Запиши адреса, имена доступных символов и выводы; если прямого соответствия нет, зафиксируй это как результат.',
                   'Вопрос для самопроверки: какой минимальный эксперимент может опровергнуть твою текущую гипотезу? Какие данные потребуются, чтобы сделать вывод уверенно?',
                   'Подсказка: настройка профиля и режима проверки в разделе «Лаборатория» позволяет сравнить одинаковое действие при разных разрешениях без изменения кода.']
    articles.append(dict(id=f'module-{idx:02d}',title=title, category=category,summary=summary,body='\n\n'.join(paragraphs),minutes=8+idx%11,symbol=icon,feature=feature))
Path(__file__).resolve().parents[1].joinpath('App/Resources/Articles.json').write_text(json.dumps(articles, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(len(articles), 'articles generated')
